playAt.example:
const { Audio } = kcds.world;
const { Vector3 } = kcds.math;

// The church bell for everyone within 150 m.
Audio.playAt('a_o_bell_kkut_kostelni', new Vector3(1530, 2125, 30), { range: 150 });

loopAt.example:
const { Audio } = kcds.world;
const { Vector3 } = kcds.math;

const pond = Audio.loopAt('a_l_amb_small_pond', new Vector3(1530, 2125, 14));
if (pond === 0) {
  console.warn('the pond sound did not start');
}

loopAt.exampleCs:
var pond = Audio.LoopAt("a_l_amb_small_pond", new Vector3(1530, 2125, 14));
if (pond == 0)
{
    Log.Warn("the pond sound did not start");
}

stopLoop.example:
const { Audio } = kcds.world;
const { Vector3 } = kcds.math;

const fire = Audio.loopAt('a_l_fire_torch', new Vector3(1530, 2125, 15));
setTimeout(() => {
  Audio.stopLoop(fire);
}, 60000);

stopLoop.exampleCs:
var fire = Audio.LoopAt("a_l_fire_torch", new Vector3(1530, 2125, 15));
Timers.SetTimeout(() =>
{
    Audio.StopLoop(fire);
}, 60000);

playFrom.exampleCs:
Events.On("playerCommand", (Player player, string command) =>
{
    if (command == "whistle")
    {
        Audio.PlayFrom("v_horse_whistle", player, new { range = 60 });
    }
});

triggerExists.example:
if (!kcds.world.Audio.triggerExists('v_horse_whistle')) {
  console.warn('this game has no horse whistle sound');
}

triggerExists.exampleCs:
if (!Audio.TriggerExists("v_horse_whistle"))
{
    Log.Warn("this game has no horse whistle sound");
}
